extends RefCounted


func run() -> int:
	var visited: Array[String] = []
	var queue: Array[String] = ["start", "node_a", "start", "node_b"]
	var count := 0
	for node in queue:
		if node not in visited:
			visited.append(node)
			count += 1
	return count

