	var valid_labels := {"intro": true, "chapter_one": true}
	var choices := [{"target": "intro"}, {"target": "missing_label"}, {"target": "chapter_one"}]
	var errors: Array[String] = []
	for choice in choices:
		var target = choice.get("target", "")
		if not valid_labels.has(target):
			errors.append(target)
	return errors

