	var known_characters := ["mario", "luigi"]
	var script_lines := [{"speaker": "mario"}, {"speaker": "peach"}, {"speaker": "luigi"}]
	var unknown_count := 0
	for line in script_lines:
		var speaker = line.get("speaker", "")
		if speaker != "" and speaker not in known_characters:
			unknown_count += 1
	return unknown_count

